/**
 * Content loading: reads Markdown files from the content directory and
 * parses each into a Page object ready for the plugin pipeline.
 */

import fs from 'fs';
import path from 'path';

import { parseFrontmatter } from './frontmatter';
import { markdownToHtml } from './markdown';
import { pageTitle } from './render';
import type { Frontmatter, Page } from './types';

/** Strip the file extension to produce a page slug. */
export function slugify(filename: string): string {
  return filename.replace(/\.[^.]+$/, '');
}

/** List Markdown files (non-recursive) inside the content directory. */
export function listMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) return [];
  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && /\.md$/i.test(entry.name))
    .map((entry) => entry.name)
    .sort();
}

/** Read and parse a single Markdown file into a Page object. */
export function readPage(fileName: string, contentDir: string): Page {
  const sourcePath = path.join(contentDir, fileName);
  const raw = fs.readFileSync(sourcePath, 'utf8');
  const { data, content } = parseFrontmatter(raw);

  const slug = slugify(fileName);
  const title = pageTitle(data, slug);

  return {
    slug,
    sourcePath,
    outputName: `${slug}.html`,
    title,
    date: data.date,
    tags: normalizePageTags(data),
    html: markdownToHtml(content),
    content,
    raw,
    data,
  };
}

function normalizePageTags(data: Frontmatter): string[] {
  return Array.isArray(data.tags) ? data.tags.map(String) : [];
}

/** Load and parse every Markdown file in the content directory. */
export function loadPages(contentDir: string): Page[] {
  return listMarkdownFiles(contentDir).map((fileName) => readPage(fileName, contentDir));
}

/**
 * Site building entry points.
 *
 * The content loaders live in `./load` and the build engine (which
 * orchestrates the plugin pipeline) lives in `./engine`. This module
 * re-exports both so the public API surface stays unchanged.
 */

export {
  listMarkdownFiles,
  loadPages,
  readPage,
  slugify,
} from './load';
export { buildSite } from './engine';

/**
 * Built-in plugin that converts the Markdown body of every page into HTML.
 */

import { markdownToHtml } from '../markdown';
import type { Plugin, PluginContext } from '../plugin';
import type { Page } from '../types';

/** Plugin name used to identify the Markdown plugin. */
export const MARKDOWN_PLUGIN_NAME = 'markdown';

/**
 * Converts `page.content` (the raw Markdown body) into `page.html` when it
 * has not been rendered yet. Pages loaded through the content loader already
 * carry their rendered HTML, in which case this is a no-op.
 */
export class MarkdownPlugin implements Plugin {
  readonly name = MARKDOWN_PLUGIN_NAME;

  onFile(page: Page, _context: PluginContext): void {
    if (!page.html) {
      page.html = markdownToHtml(page.content);
    }
  }
}

/**
 * Built-in plugin that renders pages through Handlebars templates, layouts
 * and partials. When no templates directory exists it falls back to the
 * built-in renderers.
 */

import { renderIndex, renderPage } from '../render';
import {
  DEFAULT_TEMPLATES_DIR,
  TEMPLATE_EXTENSION,
  hasTemplates,
  loadTemplates,
  renderIndexWithTemplates,
  renderPageWithTemplates,
} from '../templates';
import type { Templates } from '../templates';
import type { Plugin, PluginContext } from '../plugin';
import type { Page } from '../types';

/** Plugin name used to identify the template plugin. */
export const TEMPLATE_PLUGIN_NAME = 'templates';

/**
 * Loads the templates directory during `beforeBuild` and produces the final
 * HTML for every page and for the site index into `context.outputs`.
 */
export class TemplatePlugin implements Plugin {
  readonly name = TEMPLATE_PLUGIN_NAME;

  private templatesDir: string | null = null;
  private templates: Templates | null = null;

  beforeBuild(context: PluginContext): void {
    const templatesDir = context.options.templatesDir ?? DEFAULT_TEMPLATES_DIR;
    this.templatesDir = templatesDir;
    this.templates = hasTemplates(templatesDir) ? loadTemplates(templatesDir) : null;
  }

  onFile(page: Page, context: PluginContext): void {
    context.outputs[page.outputName] = this.templates
      ? renderPageWithTemplates(page, this.templates)
      : renderPage(page);
  }

  afterBuild(context: PluginContext): void {
    if (!this.templates || !this.templatesDir) return;
    if (this.templates.templates.has(`index.${TEMPLATE_EXTENSION}`)) {
      context.outputs['index.html'] = renderIndexWithTemplates(context.pages, this.templates);
    }
  }
}

/**
 * Built-in plugin that provides the live-reload development server.
 *
 * The plugin implements both the SSG `Plugin` lifecycle (its `afterBuild`
 * hook notifies connected browsers to reload) and the `DevServer` API so it
 * can be driven directly by `startDevServer`.
 */

import fs from 'fs';
import http from 'http';
import path from 'path';

import chokidar from 'chokidar';
import type { FSWatcher } from 'chokidar';
import WebSocket from 'ws';

import { buildSite } from '../site';
import type { Plugin, PluginContext } from '../plugin';
import type { Page } from '../types';

/** Default port used by the development server. */
export const DEFAULT_PORT = 3000;
/** WebSocket path browsers connect to for live reload notifications. */
export const RELOAD_PATH = '/__ssg_reload';
/** Debounce window (ms) used before rebuilding after a file change. */
export const REBUILD_DELAY_MS = 100;

/** Options controlling the development server. */
export interface ServeOptions {
  /** Directory containing Markdown content files. */
  contentDir: string;
  /** Directory where generated HTML files are written and served from. */
  outputDir: string;
  /** Directory containing templates, layouts and partials. */
  templatesDir: string;
  /** Port to listen on (default: {@link DEFAULT_PORT}). */
  port?: number;
}

/** A running development server instance. */
export interface DevServer {
  /** The underlying HTTP server. */
  server: http.Server;
  /** The WebSocket server used for live reload messages. */
  wss: WebSocket.WebSocketServer;
  /** The chokidar watcher watching content and templates. */
  watcher: FSWatcher;
  /** The directory being served. */
  outputDir: string;
  /** The port the server is actually bound to. */
  port: number;
  /** Rebuild the site immediately and return the built pages. */
  rebuild(): Page[];
  /** Send a reload notification to every connected browser. */
  broadcast(): void;
  /** Stop the server, watcher and all WebSocket connections. */
  close(): Promise<void>;
}

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.eot': 'application/vnd.ms-fontobject',
};

/**
 * Inject the live-reload client script into an HTML document. The script
 * opens a WebSocket to the current host and reloads the page whenever a
 * message is received.
 */
export function injectLiveReloadScript(html: string): string {
  const script = `<script>
(function () {
  var scheme = window.location.protocol === 'https:' ? 'wss://' : 'ws://';
  function connect() {
    var ws = new WebSocket(scheme + window.location.host + '${RELOAD_PATH}');
    ws.onopen = function () {};
    ws.onmessage = function (event) {
      if (event.data) { window.location.reload(); }
    };
    ws.onclose = function () { setTimeout(connect, 1000); };
  }
  connect();
})();
</script>`;

  const closingTag = '</body>';
  const closingIndex = html.toLowerCase().lastIndexOf(closingTag);
  if (closingIndex === -1) {
    return `${html}\n${script}`;
  }
  return `${html.slice(0, closingIndex)}${script}\n${closingTag}${html.slice(
    closingIndex + closingTag.length,
  )}`;
}

/** Notify every connected browser to reload. */
function notifyClients(wss: WebSocket.WebSocketServer): void {
  const data = JSON.stringify({ type: 'reload' });
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  }
}

/** Serve a single file from the output directory over the HTTP response. */
function sendFile(res: http.ServerResponse, filePath: string): void {
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
    if (ext === '.html' || ext === '.htm') {
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(injectLiveReloadScript(data.toString('utf8')));
    } else {
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(data);
    }
  });
}

/** Resolve a request URL into a safe path inside the output directory. */
function resolveRequestPath(outputDir: string, rawPath: string): string | null {
  let pathname: string;
  try {
    pathname = decodeURIComponent(rawPath);
  } catch {
    return null;
  }
  if (pathname === '/') {
    pathname = '/index.html';
  }
  const resolved = path.resolve(outputDir, `.${pathname}`);
  const relative = path.relative(outputDir, resolved);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    return null;
  }
  return resolved;
}

/** Plugin name used to identify the dev server plugin. */
export const DEV_SERVER_PLUGIN_NAME = 'dev-server';

/**
 * The live-reload development server as an SSG plugin. Registered into the
 * plugin pipeline, its `afterBuild` hook broadcasts a reload message to every
 * connected browser after each rebuild.
 */
export class DevServerPlugin implements Plugin, DevServer {
  readonly name = DEV_SERVER_PLUGIN_NAME;

  private options: ServeOptions;

  server!: http.Server;
  wss!: WebSocket.WebSocketServer;
  watcher!: FSWatcher;
  outputDir!: string;
  port!: number;

  private timer: ReturnType<typeof setTimeout> | null = null;

  constructor(options?: Partial<ServeOptions>) {
    this.options = {
      contentDir: options?.contentDir ?? 'content',
      outputDir: options?.outputDir ?? 'dist',
      templatesDir: options?.templatesDir ?? 'templates',
      port: options?.port ?? DEFAULT_PORT,
    };
  }

  /**
   * Build the site once and start serving the output directory with live
   * reload. Resolves once the server is listening.
   */
  async start(): Promise<void> {
    const { contentDir, outputDir, templatesDir } = this.options;

    this.rebuild();

    const server = http.createServer((req, res) => {
      const target = resolveRequestPath(outputDir, req.url ?? '/');
      if (!target) {
        res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Forbidden');
        return;
      }
      fs.stat(target, (statErr, stats) => {
        if (statErr || !stats.isFile()) {
          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
          res.end('Not Found');
          return;
        }
        sendFile(res, target);
      });
    });

    const wss = new WebSocket.WebSocketServer({
      server,
      path: RELOAD_PATH,
    });

    const watchTargets: string[] = [contentDir];
    if (fs.existsSync(templatesDir)) {
      watchTargets.push(templatesDir);
    }

    const watcher = chokidar.watch(watchTargets, { ignoreInitial: true });

    watcher.on('all', () => {
      if (this.timer) {
        clearTimeout(this.timer);
      }
      this.timer = setTimeout(() => {
        this.timer = null;
        this.rebuild();
        this.broadcast();
      }, REBUILD_DELAY_MS);
    });

    await new Promise<void>((resolve, reject) => {
      server.once('error', reject);
      server.listen(this.options.port, () => {
        server.removeListener('error', reject);
        resolve();
      });
    });

    const address = server.address();
    const boundPort =
      address !== null && typeof address === 'object'
        ? address.port
        : this.options.port;

    this.server = server;
    this.wss = wss;
    this.watcher = watcher;
    this.outputDir = outputDir;
    this.port = boundPort;
  }

  /** Rebuild the site immediately and return the built pages. */
  rebuild(): Page[] {
    const { contentDir, outputDir, templatesDir } = this.options;
    try {
      return buildSite({ contentDir, outputDir, templatesDir, plugins: [this] });
    } catch (error) {
      console.error('[ssg] Build failed:', error);
      return [];
    }
  }

  /** Send a reload notification to every connected browser. */
  broadcast(): void {
    if (!this.wss) return;
    notifyClients(this.wss);
  }

  /** Plugin hook: notify browsers to reload after every build. */
  afterBuild(_context: PluginContext): void {
    this.broadcast();
  }

  /** Stop the server, watcher and all WebSocket connections. */
  async close(): Promise<void> {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.watcher) {
      await this.watcher.close();
    }
    if (this.wss) {
      for (const client of this.wss.clients) {
        client.terminate();
      }
      this.wss.close();
    }
    if (this.server) {
      await new Promise<void>((resolve) => {
        this.server.close(() => resolve());
        this.server.closeAllConnections?.();
      });
    }
  }
}

/**
 * Build the site once and start a live-reload dev server that serves the
 * output directory. Returns once the server is listening.
 */
export async function startDevServer(options: ServeOptions): Promise<DevServer> {
  const plugin = new DevServerPlugin(options);
  await plugin.start();
  return plugin;
}

/**
 * Plugin configuration loading.
 *
 * Plugins are configured through a `ssg.config.ts` (or `.js`) file in the
 * working directory. The file's default export is an object whose `plugins`
 * array lists built-in plugin names and/or paths to TypeScript plugin modules
 * under `./plugins/`.
 */

import fs from 'fs';
import path from 'path';

import type { Plugin } from './plugin';
import type { BuildOptions } from './types';

/** Default config file name. */
export const DEFAULT_CONFIG_FILE = 'ssg.config.ts';

/** A config `plugins` entry: a built-in name, a module path, or a plugin. */
export type PluginSpec = string | Plugin | (() => Plugin);

/** Shape of the SSG config file. */
export interface SSGConfig {
  /** Plugins to load, in execution order (after the built-in plugins). */
  plugins?: PluginSpec[];
  [key: string]: unknown;
}

/** A config file together with the directory it was loaded from. */
export interface LoadedConfig {
  /** The parsed configuration object. */
  config: SSGConfig;
  /** Directory containing the config file (base for relative paths). */
  dir: string;
}

/** Resolve the config file path, defaulting to `./ssg.config.ts`. */
export function resolveConfigPath(configPath?: string): string {
  if (configPath) return path.resolve(configPath);
  const tsPath = path.resolve(DEFAULT_CONFIG_FILE);
  if (fs.existsSync(tsPath)) return tsPath;
  const jsPath = tsPath.replace(/\.ts$/, '.js');
  return fs.existsSync(jsPath) ? jsPath : tsPath;
}

/**
 * Load the SSG config. Missing config files (or files that cannot be loaded,
 * e.g. an uncompiled `.ts` file at runtime) yield an empty config.
 */
export function loadConfig(configPath?: string): LoadedConfig {
  const resolved = resolveConfigPath(configPath);
  const dir = path.dirname(resolved);

  if (!fs.existsSync(resolved)) {
    return { config: {}, dir };
  }

  let config = loadModule<SSGConfig>(resolved);
  if (config === null && resolved.endsWith('.ts')) {
    const jsPath = resolved.slice(0, -3) + '.js';
    if (fs.existsSync(jsPath)) {
      config = loadModule<SSGConfig>(jsPath);
    }
  }

  return { config: config ?? {}, dir };
}

/** Require a module, normalising a default export, or null on failure. */
function loadModule<T>(modulePath: string): T | null {
  try {
    const resolved = require.resolve(modulePath);
    delete require.cache[resolved];
    const mod = require(modulePath) as unknown;
    const value = (mod as { default?: T } | null)?.default ?? mod;
    return value as T;
  } catch {
    return null;
  }
}

/** Resolve a single plugin spec into a Plugin instance. */
export function resolvePluginSpec(spec: PluginSpec, baseDir: string): Plugin {
  if (typeof spec !== 'string') {
    return typeof spec === 'function' ? spec() : spec;
  }

  const builtin = BUILTIN_PLUGIN_FACTORIES[spec];
  if (builtin) return builtin();

  const modulePath = resolvePluginModule(spec, baseDir);
  if (!modulePath) {
    throw new Error(`Plugin module not found: ${spec} (searched under ${baseDir})`);
  }

  const mod = require(modulePath) as unknown;
  const value = (mod as { default?: unknown } | null)?.default ?? mod;
  if (typeof value === 'function') {
    return (value as () => Plugin)();
  }
  return value as Plugin;
}

/** Resolve a plugin module specifier to a loadable file path. */
function resolvePluginModule(spec: string, baseDir: string): string | null {
  const resolved = path.resolve(baseDir, spec);
  const candidates: string[] = [resolved];

  if (!path.extname(resolved)) {
    candidates.push(`${resolved}.ts`, `${resolved}.js`, `${resolved}.cjs`);
  }

  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return null;
}

/** The built-in plugins available to every build. */
export function builtinPlugins(): Plugin[] {
  return BUILTIN_PLUGIN_FACTORIES.markdown() && BUILTIN_PLUGIN_FACTORIES.templates()
    ? [BUILTIN_PLUGIN_FACTORIES.markdown(), BUILTIN_PLUGIN_FACTORIES.templates()]
    : [];
}

/**
 * Assemble the full plugin list for a build: the built-in markdown and
 * template plugins first, then any plugins listed in the config file, then
 * any plugins passed directly through the build options.
 */
export function loadPlugins(
  loaded: LoadedConfig,
  options?: BuildOptions,
): Plugin[] {
  const plugins: Plugin[] = builtinPlugins();

  for (const spec of loaded.config.plugins ?? []) {
    plugins.push(resolvePluginSpec(spec, loaded.dir));
  }

  for (const plugin of options?.plugins ?? []) {
    plugins.push(plugin);
  }

  return plugins;
}

const BUILTIN_PLUGIN_FACTORIES: Record<string, () => Plugin> = {
  markdown: () => new MarkdownPlugin(),
  templates: () => new TemplatePlugin(),
  'dev-server': () => new DevServerPlugin(),
};

// Late imports avoid a require-time cycle between config and the plugins.
import { DevServerPlugin } from './plugins/dev-server';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';

